// Domain-neutral. MISI N fixes three defects found by clean-room testing:
//  (1) The old version DROPPED every non-due row, so the If node's FALSE
//      output could never fire. Every row now leaves this node with an
//      explicit needs_action boolean, and both If outputs are reachable.
//  (2) Duplicate record_id values produced duplicate outbound messages.
//      A stable row key now de-duplicates the input before any send.
//  (3) A retry after a successful write-back re-sent the same message.
//      Terminal statuses are skipped, and Mark Contacted writes a terminal
//      status so the second run is a no-op.
const cfg = $('CONFIG').first().json;
const batas = Number(cfg.due_days || 3);
const terminal = new Set(['done', 'contacted', 'sent', 'complete', 'completed', 'paid']);
const seen = new Set();
const keluar = [];
for (const item of $input.all()) {
  const p = item.json;
  const key = String(p.record_id !== undefined && p.record_id !== null
    ? p.record_id : (String(p.email) + '|' + String(p.item_ref)));
  if (seen.has(key)) continue;
  seen.add(key);
  const status = String(p.status || '').toLowerCase();
  const t = new Date(String(p.last_activity) + 'T00:00:00Z').getTime();
  const days = Number.isFinite(t) ? Math.max(0, Math.floor((Date.now() - t) / 86400000)) : 0;
  const needs = !terminal.has(status) && days >= batas;
  keluar.push({ json: Object.assign({}, p, { days_since: days, needs_action: needs }) });
}
return keluar;

// Generic token merge: the node does not know which domain it is serving.
const cfg = $('CONFIG').first().json;
const tpl = String(cfg.message_template || '');
const subjTpl = String(cfg.subject_template || '');
const peta = { name: 'contact_name', item: 'item_ref', days: 'days_since' };
const isi = function (s, p) {
  return String(s).replace(/\{\{([a-z_]+)\}\}/g, function (m, k) {
    const f = peta[k];
    return (f && p[f] !== undefined && p[f] !== null) ? String(p[f]) : m;
  });
};
return $input.all().map(function (item) {
  const p = item.json;
  return { json: Object.assign({}, p, {
    recipient: p.email,
    subject: isi(subjTpl, p),
    message: isi(tpl, p)
  }) };
});
